        }
      ]
    },
    {
      "id": "build_image",
      "description": "Build Docker image",
      "action": "docker build",
      "target": "docker_image",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "Dockerfile is present",
          "fact": "dockerfile_exists",
          "established_by": "revert_commit"
        }
      ]
    },
    {
      "id": "deploy_image",
      "description": "Deploy Docker image to production with kubectl",
      "action": "kubectl apply",
      "target": "k8s_deployment",
      "risk_class": "high",
      "rollback": {
        "trigger": "deployment fails",
        "action": "rollback to previous deployment",
        "safety_guard": "check prior deployment health"
      },
      "verification": {
        "what": "deployment status",
        "how": "kubectl rollout status",
        "expected": "deployment is complete and healthy"
      },
      "preconditions": [
        {
          "description": "Docker image is built",
          "fact": "image_built",
          "established_by": "build_image"
        }
      ]
    },
    {
      "id": "verify_downstream",
      "description": "Verify downstream services are functional",
      "action": "check services",
      "target": "downstream_services",
      "risk_class": "critical",
      "rollback": {
        "trigger": "verification fails",
        "action": "revert deployment",
        "safety_guard": "ensure backups are valid"
      },
      "verification": {
        "what": "service health checks",
        "how": "execute health check endpoints",
        "expected": "all services return healthy status"
      },
      "preconditions": [
        {
          "description": "Kubernetes deployment is completed",
          "fact": "deployment_successful",
          "established_by": "deploy_image"
        }
      ]
    }
  ],
  "dependencies": [
    {
      "from_task": "revert_commit",
      "to_task": "build_image",
      "kind": "hard"
    },
    {
      "from_task": "build_image",
      "to_task": "deploy_image",
      "kind": "hard"
    },
    {
      "from_task": "deploy_image",
      "to_task": "verify_downstream",
      "kind": "hard"
    }
  ],
  "branches": []
}

